-- Display names, hiragana readings, and group-term aliases.
-- Backup tables keep the previous display_name and reading, and
-- every alias row, so the label update can be reversed without
-- deleting meal logs. Existing karonavi_alias_v1 rows are not
-- updated: inserts conflict on (food_code, normalized) and skip.
-- On an empty table (CI, before the sample import) the data
-- statements match nothing.

create table if not exists public.official_foods_label_backup_20260929 as
select food_code, display_name, reading
from public.official_foods;

create table if not exists public.official_food_aliases_backup_20260929 as
select *
from public.official_food_aliases;

alter table public.official_foods_label_backup_20260929 enable row level security;
alter table public.official_food_aliases_backup_20260929 enable row level security;
revoke all on table public.official_foods_label_backup_20260929 from public, anon, authenticated;
revoke all on table public.official_food_aliases_backup_20260929 from public, anon, authenticated;

alter table public.official_foods
  add column if not exists normalized_reading text;

alter table public.official_food_aliases
  add column if not exists normalized_reading text;

alter table public.official_food_aliases
  add column if not exists is_group boolean not null default false;

comment on column public.official_food_aliases.is_group is
  'Wide words such as 牛肉. Every matching food is a candidate.';

create or replace function public.official_foods_fill_normalized_reading()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_table_name = 'official_foods' then
    new.normalized_reading := public.normalize_food_search_text(new.reading);
  else
    new.normalized_reading := public.normalize_food_search_text(coalesce(new.reading, new.alias));
  end if;
  return new;
end;
$$;

revoke all on function public.official_foods_fill_normalized_reading() from public, anon, authenticated;

drop trigger if exists official_foods_fill_normalized_reading on public.official_foods;
create trigger official_foods_fill_normalized_reading
  before insert or update of reading on public.official_foods
  for each row
  execute function public.official_foods_fill_normalized_reading();

drop trigger if exists official_food_aliases_fill_normalized_reading on public.official_food_aliases;
create trigger official_food_aliases_fill_normalized_reading
  before insert or update of reading, alias on public.official_food_aliases
  for each row
  execute function public.official_foods_fill_normalized_reading();

do $$
declare
  opschema text;
begin
  select n.nspname into opschema
  from pg_opclass c
  join pg_namespace n on n.oid = c.opcnamespace
  where c.opcname = 'gin_trgm_ops'
  order by case when n.nspname = 'extensions' then 0 else 1 end
  limit 1;
  if opschema is null then
    raise exception 'gin_trgm_ops is missing';
  end if;
  if not exists (
    select 1 from pg_indexes
    where schemaname = 'public'
      and indexname = 'official_foods_normalized_reading_trgm_idx'
  ) then
    execute format(
      'create index official_foods_normalized_reading_trgm_idx on public.official_foods using gin (normalized_reading %I.gin_trgm_ops)',
      opschema
    );
  end if;
  if not exists (
    select 1 from pg_indexes
    where schemaname = 'public'
      and indexname = 'official_food_aliases_normalized_reading_trgm_idx'
  ) then
    execute format(
      'create index official_food_aliases_normalized_reading_trgm_idx on public.official_food_aliases using gin (normalized_reading %I.gin_trgm_ops)',
      opschema
    );
  end if;
end
$$;

create index if not exists official_food_aliases_group_term_idx
  on public.official_food_aliases (normalized, normalized_reading)
  where is_group;

create or replace function public.search_official_foods(
  p_query text,
  p_limit integer default 30
)
returns table (
  food_code text,
  food_group text,
  index_no text,
  name text,
  display_name text,
  reading text,
  base_amount numeric,
  unit_type text,
  refuse_pct numeric,
  kcal numeric,
  protein_g numeric,
  fat_g numeric,
  carb_g numeric,
  fiber_g numeric,
  salt_eq_g numeric,
  matched_alias text,
  matched_alias_reading text,
  match_rank integer,
  is_candidate boolean,
  candidate_rank integer
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  -- Character cap, same as OfficialFoodLimits.maxQueryLength. Applied
  -- before normalization so a huge argument never enters the per-character
  -- loop. The pattern is inlined as a literal so the planner can use the
  -- gin_trgm_ops indexes on the stored columns.
  v_raw text := pg_catalog.left(coalesce(p_query, ''), 64);
  v_query text := pg_catalog.left(public.normalize_food_search_text(v_raw), 64);
  v_pattern text;
  v_limit integer := least(greatest(coalesce(p_limit, 30), 0), 100);
begin
  if v_query = '' or v_limit = 0 then
    return;
  end if;

  -- Group words (牛肉, 肉, 魚, チキン, …) return every member.
  -- The client asks for 30, which would hide the rest.
  if exists (
    select 1
    from public.official_food_aliases as group_alias
    where group_alias.is_group
      and (
        group_alias.normalized = v_query
        or group_alias.normalized_reading = v_query
      )
  ) then
    v_limit := 800;
  end if;

  v_pattern :=
    '%'
    || pg_catalog.replace(
         pg_catalog.replace(
           pg_catalog.replace(v_query, '\', '\\'),
           '%',
           '\%'
         ),
         '_',
         '\_'
       )
    || '%';

  -- One indexed column per arm. OR would hide the index, and wrapping the
  -- column in normalize_food_search_text would too. normalized_name and
  -- aliases.normalized are already the search key. Human reading keeps
  -- the long vowel. normalized_reading is the search key.
  return query execute format(
    $sql$
    with hits as (
      select
        f.food_code,
        f.food_group,
        f.index_no,
        f.name,
        f.display_name,
        f.reading,
        f.base_amount,
        f.unit_type,
        f.refuse_pct,
        f.kcal,
        f.protein_g,
        f.fat_g,
        f.carb_g,
        f.fiber_g,
        f.salt_eq_g,
        null::text as matched_alias,
        null::text as matched_alias_reading,
        100 as priority,
        false as is_candidate,
        null::integer as candidate_rank,
        case
          when f.normalized_name = %L then 0
          when pg_catalog.strpos(f.normalized_name, %L) = 1 then 1
          when pg_catalog.strpos(f.normalized_name, %L) > 0 then 2
          else 9
        end as rank_value
      from public.official_foods f
      where f.normalized_name like %L escape '\'
      union all
      select
        f.food_code,
        f.food_group,
        f.index_no,
        f.name,
        f.display_name,
        f.reading,
        f.base_amount,
        f.unit_type,
        f.refuse_pct,
        f.kcal,
        f.protein_g,
        f.fat_g,
        f.carb_g,
        f.fiber_g,
        f.salt_eq_g,
        null::text as matched_alias,
        null::text as matched_alias_reading,
        100 as priority,
        false as is_candidate,
        null::integer as candidate_rank,
        case
          when f.normalized_reading = %L then 0
          when pg_catalog.strpos(f.normalized_reading, %L) = 1 then 1
          when pg_catalog.strpos(f.normalized_reading, %L) > 0 then 2
          else 9
        end as rank_value
      from public.official_foods f
      where f.normalized_reading like %L escape '\'
      union all
      select
        f.food_code,
        f.food_group,
        f.index_no,
        f.name,
        f.display_name,
        f.reading,
        f.base_amount,
        f.unit_type,
        f.refuse_pct,
        f.kcal,
        f.protein_g,
        f.fat_g,
        f.carb_g,
        f.fiber_g,
        f.salt_eq_g,
        a.alias,
        a.reading,
        a.priority,
        a.is_candidate,
        a.candidate_rank,
        case
          when a.normalized = %L then 0
          when pg_catalog.strpos(a.normalized, %L) = 1 then 1
          when pg_catalog.strpos(a.normalized, %L) > 0 then 2
          else 9
        end as rank_value
      from public.official_food_aliases a
      join public.official_foods f on f.food_code = a.food_code
      where a.normalized like %L escape '\'
      union all
      select
        f.food_code,
        f.food_group,
        f.index_no,
        f.name,
        f.display_name,
        f.reading,
        f.base_amount,
        f.unit_type,
        f.refuse_pct,
        f.kcal,
        f.protein_g,
        f.fat_g,
        f.carb_g,
        f.fiber_g,
        f.salt_eq_g,
        a.alias,
        a.reading,
        a.priority,
        a.is_candidate,
        a.candidate_rank,
        case
          when a.normalized_reading = %L then 0
          when pg_catalog.strpos(a.normalized_reading, %L) = 1 then 1
          when pg_catalog.strpos(a.normalized_reading, %L) > 0 then 2
          else 9
        end as rank_value
      from public.official_food_aliases a
      join public.official_foods f on f.food_code = a.food_code
      where a.normalized_reading like %L escape '\'
    ),
    matched as (
      select *
      from hits
      where rank_value < 9
    ),
    best as (
      select distinct on (matched.food_code)
        matched.*
      from matched
      order by
        matched.food_code,
        matched.rank_value,
        matched.is_candidate,
        matched.candidate_rank nulls last,
        (matched.matched_alias is null),
        matched.priority,
        matched.matched_alias
    )
    select
      best.food_code,
      best.food_group,
      best.index_no,
      best.name,
      best.display_name,
      best.reading,
      best.base_amount,
      best.unit_type,
      best.refuse_pct,
      best.kcal,
      best.protein_g,
      best.fat_g,
      best.carb_g,
      best.fiber_g,
      best.salt_eq_g,
      best.matched_alias,
      best.matched_alias_reading,
      best.rank_value,
      best.is_candidate,
      best.candidate_rank
    from best
    order by
      best.rank_value,
      best.is_candidate,
      best.candidate_rank nulls last,
      (best.matched_alias is null),
      best.priority,
      best.food_code
    limit %s
    $sql$,
    v_query, v_query, v_query, v_pattern,
    v_query, v_query, v_query, v_pattern,
    v_query, v_query, v_query, v_pattern,
    v_query, v_query, v_query, v_pattern,
    v_limit
  );
end;
$$;


