) as incoming(
  food_code, alias, reading, normalized, is_candidate,
  candidate_rank, note, is_group
)
where exists (
  select 1 from public.official_foods as food
  where food.food_code = incoming.food_code
)
on conflict (food_code, normalized) do nothing;

update public.official_foods
set normalized_reading = public.normalize_food_search_text(reading)
where normalized_reading is null;

update public.official_food_aliases
set normalized_reading = public.normalize_food_search_text(coalesce(reading, alias))
where normalized_reading is null;
